import { Dialog, Transition } from "@headlessui/react";
import React, { Fragment } from "react";
import { useSidebar } from "../Context/context";

const DeleteModal = () => {
    const { deletemodel, setDeletemodel, messageToDelete, setMessageToDelete, messagess, setMessagess } = useSidebar();
  
    const handleConfirmDelete = () => {
      if (messageToDelete !== null) {
        setMessagess(messagess.filter((m) => m.id !== messageToDelete)); 
        setMessageToDelete(null);
      }
      setDeletemodel(false);
    };
  
    return (
      <Transition appear as={Fragment} show={deletemodel}>
        <Dialog as="div" className="relative z-50" onClose={() => setDeletemodel(false)}>
          <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-md" />
          <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="bg-white p-6 rounded-lg shadow-lg max-w-sm w-full">
              <Dialog.Title className="text-lg font-bold">Confirm Deletion</Dialog.Title>
              <Dialog.Description className="mt-2 text-gray-600">
                Are you sure you want to delete this message? This action cannot be undone.
              </Dialog.Description>
              <div className="mt-4 flex justify-end space-x-3">
                <button className="px-4 py-2 bg-gray-300 rounded hover:bg-gray-400" onClick={() => setDeletemodel(false)}>
                  Cancel
                </button>
                <button className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700" onClick={handleConfirmDelete}>
                  Delete
                </button>
              </div>
            </Dialog.Panel>
          </div>
        </Dialog>
      </Transition>
    );
  };
  
  export default DeleteModal;
  
